  color: #fbbf24;
  font-weight: 700;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width:560px) {
  .page {
    place-items: start center;
    padding: 14px;
  }

  .card {
    padding: 16px;
    border-radius: 15px;
  }

  .chip-field {
    padding: 9px;
  }

  .chip {
    width: 100%;
    justify-content: space-between;
  }

  .chip-input {
    min-width: 120px;
    flex-basis: 100%;
  }

  .supporting-copy {
    display: grid;
    gap: 7px;
  }

  .invite-limit {
    justify-self: start;
  }

  .suggestions {
    max-height: 230px;
  }
}

